import { useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { useApp } from "./context/AppContext";

export default function ChatroomPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { chatrooms, sendChatMessage, user } = useApp();
  const [text, setText] = useState("");

  const room = chatrooms.find((c) => c.id === id);

  if (!room) {
    return (
      <div className="chatroom-page">
        <button
          type="button"
          className="back-btn"
          onClick={() => navigate("/feed")}
        >
          ← Back to Feed
        </button>
        <p className="status-msg">Chatroom not found.</p>
      </div>
    );
  }

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!text.trim()) return;
    sendChatMessage(room.id, text.trim(), user || "you");
    setText("");
  };

  return (
    <div className="chatroom-page">
      <button
        type="button"
        className="back-btn"
        onClick={() => navigate("/feed")}
      >
        ← Back to Feed
      </button>
      <div className="chatroom-header">
        <span className="chatroom-icon">{room.icon}</span>
        <h1>{room.title}</h1>
      </div>
      <div className="chat-messages">
        {room.messages.map((m) => (
          <div key={m.id} className="chat-message">
            <span className="comment-author">{m.author}</span>
            <p className="comment-text">{m.text}</p>
          </div>
        ))}
      </div>
      <form className="comment-form chat-input-form" onSubmit={handleSubmit}>
        <input
          type="text"
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder="Type a message…"
          aria-label="Chat message"
        />
        <button type="submit" className="btn-primary">
          Send
        </button>
      </form>
    </div>
  );
}
